import re


class ScanCounters(object):
    def __init__(self, measurements, use_kpi, counter_need, type_kpi):
        """

        :param measurements:
        :param use_kpi:
        :param counter_need:
        """
        self.__measurements = measurements
        self.__use_kpi = use_kpi
        self.__counter_need = counter_need
        self.__type_kpi = type_kpi
        self.__kpi_exceptions = {}
        self.__exceptions = []
        self.__cells = set()

    @property
    def cells(self):
        """

        :return:
        """
        return self.__cells

    @property
    def kpi_exceptions(self):
        """

        :return:
        """
        return self.__kpi_exceptions

    def scan(self):
        """

        :return:
        """
        for measurement_time in self.__measurements:
            for counter in self.__measurements[measurement_time].parameters:
                for dn in self.__measurements[measurement_time].parameters[counter]:
                    self.__scan_dn(dn, counter)

    def __scan_dn(self, dn, counter):
        """

        :param dn:
        :param counter:
        :return:
        """
        regex_4G = r'(?P<OBJECT>LNCEL-\d+)'
        regex_5G = r'(?P<OBJECT>NRCELL-\d+)'

        match_4G = re.search(regex_4G, dn)
        match_5G = re.search(regex_5G, dn)
        if match_4G and self.__type_kpi == 'LTE':
            self.__cells.add(match_4G.group('OBJECT'))
        elif match_5G and self.__type_kpi == '5G':
            self.__cells.add(match_5G.group('OBJECT'))
        else:
            for exception in self.__exceptions:
                regex = r'(?P<OBJECT>{}-\d+)'.format(exception)
                match = re.search(regex, dn)
                if match:
                    self.__add_exception(match.group('OBJECT'), counter)

    def __add_exception(self, exception_number, exception_counter):
        """

        :param exception_number:
        :param exception_counter:
        :return:
        """
        exception_counter = re.findall(r'\[(.*)\]', exception_counter)[0]
        if exception_counter in self.__counter_need:
            for kpi in self.__use_kpi:
                if exception_counter in self.__use_kpi[kpi]['DEPENDENCIES']:
                    if kpi not in self.__kpi_exceptions:
                        self.__kpi_exceptions[kpi] = set()
                    self.__kpi_exceptions[kpi].add(exception_number)
